def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        if tz is None:
            import datetime
            return datetime.time.fromtimestamp(nanoseconds / 1e9)
        else:
            import datetime
            import pytz
            tz = pytz.timezone(tz)
            return tz.localize(datetime.datetime.fromtimestamp(nanoseconds / 1e9)).time()
    except (ValueError, pytz.UnknownTimeZoneError) as e:
        raise ValueError(f"Error hydrating time: {e}")

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if not isinstance(value, timedelta):
        raise TypeError("Expected a timedelta, got {}".format(type(value).__name__))
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if not isinstance(value, Time):
        raise ValueError("Expected a Time object, got: {}".format(type(value)))
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Expected a Point instance, got {}".format(type(value).__name__))

    return {'x': value.x, 'y': value.y}

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self.record.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    if not hasattr(self, '_data'):
        raise AttributeError("This object does not have an indexable attribute '_data'")

    if key not in self._data:
        raise ValueError(f"{key} is not in the list")

    return self._data.index(key)

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self.__dict__.values())
    else:
        values = []
        for key in keys:
            try:
                values.append(self.__dict__[key])
            except KeyError:
                try:
                    # Assuming keys could also be integer indexes
                    values.append(list(self.__dict__.values())[key])
                except IndexError:
                    # If neither key nor index is valid, we skip it
                    pass
        return values

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        return dict(zip(self.__fields__, self.__values__))
    for key in keys:
        try:
            if isinstance(key, int):
                if key >= len(self.__values__):
                    raise IndexError(f"Index {key} is out of bounds for the record.")
                result[self.__fields__[key]] = self.__values__[key]
            else:
                try:
                    index = self.__fields__.index(key)
                    result[key] = self.__values__[index]
                except ValueError:
                    result[key] = None
        except IndexError as e:
            raise IndexError(e)
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    from collections import namedtuple

    if not isinstance(name, str) or not name:
        raise ValueError("Name must be a non-empty string.")

    if not isinstance(fields, list) or not all(isinstance(f, str) for f in fields) or not fields:
        raise ValueError("Fields must be a non-empty list of strings.")

    if not isinstance(srid_map, dict) or not all(isinstance(k, int) for k in srid_map.keys()):
        raise ValueError("SRID map must be a dictionary with integer keys.")

    class DynamicPoint(namedtuple(name, fields)):
        __slots__ = ()  # Prevents the creation of instance dictionaries, keeping memory usage low

        def __new__(cls, *args, srid=4326, **kwargs):
            if srid not in srid_map:
                raise ValueError(f"SRID {srid} is not in the SRID map.")
            return super(DynamicPoint, cls).__new__(cls, *args, **kwargs)

        def __init__(self, *args, srid=4326, **kwargs):
            self._srid = srid

        @property
        def srid(self):
            return self._srid

    return DynamicPoint

import warnings
import functools

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if not seq:
        return []
    return sorted(seq, key=lambda x: hash(x))

