def directlyProvidedBy(object): # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    if hasattr(object, '__providedBy__'):
        return object.__providedBy__
    else:
        from zope.interface.declarations import implementedBy
        from zope.interface.declarations import providedBy
        if hasattr(object, '__class__'):
            return implementedBy(object.__class__) + providedBy(object)
        else:
            return providedBy(object)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        if all(not issubclass(cls, other) for other in minimal if cls is not other):
            minimal.append(cls)
    return minimal

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    try:
        if all:
            return self._interface.attribs
        else:
            return {key: value for key, value in self._interface.attribs.items() if key in self._interface.required_attribs}
    except AttributeError:
        raise ValueError("Interface not properly defined or missing attributes.")

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if all:
        return list(self.__dict__.keys())
    else:
        return [key for key in self.__dict__ if not key.startswith('_')]

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        if isinstance(item, tuple):
            _normalizeargs(item, output)
        elif hasattr(item, 'interfaces'):
            _normalizeargs(item.interfaces, output)
        else:
            output.append(item)

    return output

