def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not isinstance(bins, (list, tuple)) or not isinstance(edges, (list, tuple)):
        raise ValueError("Both bins and edges must be lists or tuples.")
    if len(bins) != len(edges) - 1:
        raise ValueError("The number of bins must be one less than the number of edges.")

    total = 0.0
    try:
        for i in range(len(bins)):
            width = edges[i + 1] - edges[i]
            if width < 0:
                raise ValueError("Edges must be in non-decreasing order.")
            total += bins[i] * width
    except TypeError:
        raise ValueError("All elements in bins and edges must be numbers.")

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        if isinstance(seq, FillRequest):
            return True
        if hasattr(seq, '__iter__'):
            for item in seq:
                if isinstance(item, FillRequest):
                    if not isinstance(seq, Source):
                        return True
        return False
    except Exception:
        return False

