def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both arguments must be dictionaries.")

    if level == 0:
        return {}

    diff = {}
    for key, value in d1.items():
        if key not in d2:
            diff[key] = value
        elif isinstance(value, dict) and isinstance(d2[key], dict) and level != 1:
            sub_diff = difference(value, d2[key], level - 1)
            if sub_diff:
                diff[key] = sub_diff
        elif value != d2[key]:
            diff[key] = value

    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        if 0 <= coord < len(self.histogram):
            self.histogram[coord] += weight
    except (TypeError, IndexError):
        # Ignore if coord is not an integer or out of bounds
        pass

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from collections.abc import Hashable

    key_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')  # Example regex for keys
    value_regex = re.compile(r'^[a-zA-Z0-9_\- ]+$')  # Example regex for values

    errors = []

    for key, value in labels.items():
        if not isinstance(key, Hashable):
            errors.append({str(key): 'label key must be a hashable type'})
        elif isinstance(key, str) and not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex {key_regex.pattern}"})

        if isinstance(value, str):
            if not value_regex.match(value):
                errors.append({value: f"Label value '{value}' does not match the regex {value_regex.pattern}"})
        elif isinstance(value, list):
            for v in value:
                if not isinstance(v, str):
                    errors.append({str(v): 'expected string or bytes-like object'})
                elif not value_regex.match(v):
                    errors.append({v: f"Label value '{v}' does not match the regex {value_regex.pattern}"})
        else:
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(messages=errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}

    for key, value in manifest_dict.items():
        if first_level and key in ['apiVersion', 'kind', 'metadata']:
            if isinstance(value, dict) and 'name' in value:
                observer_schema[key] = {'name': value['name']}
            elif isinstance(value, dict):
                observer_schema[key] = value
            else:
                observer_schema[key] = value
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            observer_schema[key] = None

    return observer_schema

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, schema in observer_schema.items():
        if field in response:
            if isinstance(schema, dict):
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], schema, response[field]
                )
            else:
                last_applied_manifest[field] = response[field]
        else:
            raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Application object does not contain a valid spec.manifest")

        for resource_name, resource in app.spec.manifest.items():
            if resource_name not in app.observer_schema:
                # Assuming a default schema structure, this should be customized based on actual needs
                default_schema = {
                    "type": "object",
                    "properties": {
                        "status": {
                            "type": "object",
                            "properties": {
                                "conditions": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "properties": {
                                            "type": {"type": "string"},
                                            "status": {"type": "string"},
                                            "lastProbeTime": {"type": "string", "format": "date-time"},
                                            "lastTransitionTime": {"type": "string", "format": "date-time"},
                                            "reason": {"type": "string"},
                                            "message": {"type": "string"}
                                        },
                                        "required": ["type", "status"]
                                    }
                                }
                            }
                        }
                    }
                }
                app.observer_schema[resource_name] = default_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        status = self.status
    except AttributeError:
        return f"{prefix}Status not available"
    if status is None:
        return f"{prefix}No validation status"
    return f"{prefix}Validation {'Passed' if status else 'Failed'}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not hasattr(self, 'validation_log') or not self.validation_log:
        return prefix + "No validation log available."
    return prefix + "\n".join(self.validation_log)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    try:
        manifest_digests = set()
        for manifest_file in manifest_files:
            with open(manifest_file, 'r') as file:
                for line in file:
                    digest = line.split()[0]
                    manifest_digests.add(digest.strip())

        for digest in digests_used:
            if digest not in manifest_digests:
                raise ValueError(f"Digest {digest} is used but not present in the manifest files.")

    except FileNotFoundError:
        raise FileNotFoundError("One or more manifest files were not found.")
    except Exception as e:
        raise Exception(f"An error occurred while checking digests: {str(e)}")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The prior version must be an InventoryValidator object.")

    if prior.version >= self.version:
        raise ValueError("The prior version must be older than the current version.")

    # Check for consistency in inventory items
    for item_id, current_item in self.inventory.items():
        if item_id not in prior.inventory:
            raise ValueError(f"Item {item_id} present in current inventory is missing in the prior inventory.")
        prior_item = prior.inventory[item_id]
        if prior_item.version >= current_item.version:
            raise ValueError(f"Item {item_id} in the prior inventory is not older than the current version.")
        # Additional checks can be added here as per specific requirements

    # Check for removed items in the current inventory
    for item_id in prior.inventory:
        if item_id not in self.inventory:
            raise ValueError(f"Item {item_id} present in the prior inventory is missing in the current inventory.")

    # Additional overall consistency checks can be added here as per specific requirements

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    try:
        if version not in inventory:
            raise ValueError(f"Version {version} not found in inventory.")

        for logical_path, details in inventory.get(version, {}).items():
            files = set()
            for file_info in details.get('files', []):
                files.add(file_info['path'])
            logical_path_map[logical_path] = files

    except Exception as e:
        print(f"An error occurred: {e}")

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary.")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list.")

    for file_id, file_fixity in fixity.items():
        if file_id not in manifest_files:
            raise ValueError(f"File ID '{file_id}' in fixity block not found in manifest.")

        if not isinstance(file_fixity, dict):
            raise ValueError(f"Fixity data for file ID '{file_id}' must be a dictionary.")

        if 'algorithm' not in file_fixity or 'value' not in file_fixity:
            raise ValueError(f"Fixity data for file ID '{file_id}' must contain 'algorithm' and 'value' keys.")

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except FileNotFoundError:
        return []
    except Exception as e:
        return []

def add_rendition(self, lang, file_path):
    """Adds a rendition to the element.

    Parameters:
        lang (str): The language code for the rendition.
        file_path (str): The file path to the rendition.
    """
    if not isinstance(lang, str) or not isinstance(file_path, str):
        raise ValueError("Both lang and file_path must be strings.")

    if not hasattr(self, 'renditions'):
        self.renditions = {}

    if lang in self.renditions:
        raise DuplicateAnnotationError(f"A rendition for language '{lang}' already exists.")

    self.renditions[lang] = file_path

def fix_namespace_prefix_w(content):
