def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    try:
        indent_str = '  ' * indent
        result = f"{indent_str}<{self.__class__.__name__}>\n"
        for attr, value in self.__dict__.items():
            if not attr.startswith('_'):
                if isinstance(value, list):
                    result += f"{indent_str}  {attr}:\n"
                    for item in value:
                        if hasattr(item, 'pretty'):
                            result += item.pretty(indent + 2, debug)
                        else:
                            result += f"{indent_str}    {item}\n"
                elif hasattr(value, 'pretty'):
                    result += f"{indent_str}  {attr}:\n"
                    result += value.pretty(indent + 2, debug)
                else:
                    result += f"{indent_str}  {attr}: {value}\n"
        return result
    except Exception as e:
        if debug:
            return f"{indent_str}<{self.__class__.__name__} Error: {str(e)}>\n"
        else:
            return f"{indent_str}<{self.__class__.__name__}>\n"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    def apply_absorption(expr):
        # Check for absorption law: A & (A | B) = A, A | (A & B) = A
        if (len(expr) == 3 and
            (expr[0] == expr[2] or (isinstance(expr[2], tuple) and expr[0] == expr[2][1]))):
            if expr[1] == '&':
                if isinstance(expr[2], tuple) and expr[2][0] == '|':
                    return expr[0]
            elif expr[1] == '|':
                if isinstance(expr[2], tuple) and expr[2][0] == '&':
                    return expr[0]
        return expr

    def apply_negative_absorption(expr):
        # Check for negative absorption law: A & (~A | B) = A & B, A | (~A & B) = A | B
        if (len(expr) == 3 and isinstance(expr[2], tuple) and len(expr[2]) == 3 and expr[2][0] == '~'):
            if expr[1] == '&':
                if expr[0] == expr[2][1]:
                    return (expr[0], '&', expr[2][2])
            elif expr[1] == '|':
                if expr[0] == expr[2][1]:
                    return (expr[0], '|', expr[2][2])
        return expr

    new_args = []
    for expr in args:
        if isinstance(expr, tuple):
            # Apply absorption and negative absorption recursively
            new_expr = apply_absorption(expr)
            new_expr = apply_negative_absorption(new_expr)
            if new_expr != expr:
                # If expression changed, recursively apply absorption
                new_expr = apply_absorption(new_expr)
                new_expr = apply_negative_absorption(new_expr)
            new_args.append(new_expr)
        else:
            new_args.append(expr)

    return new_args

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    if not isinstance(user, str):
        raise ValueError("User must be a string.")
    if not isinstance(etcd_host, str):
        raise ValueError("etcd_host must be a string.")
    if not isinstance(etcd_port, int):
        raise ValueError("etcd_port must be an integer.")
    if etcd_port <= 0:
