        'etcd_host': etcd_host,
        'etcd_port': etcd_port
    }

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        # Attempt to get the result from the namefunc
        result = namefunc()
        # Check if the result is a tuple and contains unicode strings
        if isinstance(result, tuple) and all(isinstance(s, str) for s in result):
            # Convert each unicode string to a bytestring
            return tuple(s.encode('utf-8') for s in result)
        return result
    except Exception as e:
        # Handle any unexpected exceptions
        raise RuntimeError("Failed to process tzname function result: {}".format(e))

