def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, (list, tuple)):
        raise ValueError("Commands must be a list or tuple.")
    if not isinstance(args, (list, tuple)):
        raise ValueError("Arguments must be a list or tuple.")

    full_command = commands + args

    if verbose:
        print("Running command:", " ".join(full_command))

    try:
        env = env or os.environ
        with subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE) as process:
            stdout, stderr = process.communicate()
            if process.returncode != 0:
                error_message = f"Command {' '.join(full_command)} failed with return code {process.returncode}"
                if stderr:
                    error_message += f"\nError: {stderr.decode().strip()}"
                raise subprocess.CalledProcessError(process.returncode, full_command, output=stdout, stderr=stderr)
            if verbose:
                print("Output:", stdout.decode().strip())
            return stdout.decode().strip()
    except FileNotFoundError:
        raise FileNotFoundError(f"One of the commands in {commands} was not found.")
    except subprocess.SubprocessError as e:
        raise RuntimeError(f"An error occurred while running the command: {e}")

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorator(func):
        def wrapper(*args, **kwargs):
            if args[0].vcs == vcs:
                return method(func, *args, **kwargs)
            else:
                raise ValueError(f"VCS {vcs} is not supported by this handler.")
        return wrapper
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        for obj in self.iterate_objects():
            num_objects += 1
            if validate_objects:
                if not obj.is_valid():
                    if show_warnings:
                        print(f"Warning: Object {obj.id} is not valid.")
                    continue
            if check_digests:
                if not obj.check_digest():
                    if show_warnings:
                        print(f"Warning: Digest mismatch for object {obj.id}.")
                    continue
            good_objects += 1
    except Exception as e:
        if show_warnings:
            print(f"Error during validation: {e}")

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of version directory names.")

    root_inventory = {}
    try:
        with open(os.path.join(self.root_dir, 'root_inventory.txt'), 'r') as f:
            for line in f:
                digest, filepath = line.strip().split()
                root_inventory[filepath] = digest
    except FileNotFoundError:
        raise FileNotFoundError("Root inventory file not found.")
    except Exception as e:
        raise Exception(f"Error reading root inventory: {e}")

    for version in version_dirs:
        version_dir = os.path.join(self.root_dir, version)
        inventory_file = os.path.join(version_dir, 'inventory.txt')
        if not os.path.exists(inventory_file):
            raise FileNotFoundError(f"Inventory file not found for version {version}.")

        with open(inventory_file, 'r') as f:
            version_inventory = {}
            for line in f:
                digest, filepath = line.strip().split()
                version_inventory[filepath] = digest

            for filepath, digest in version_inventory.items():
                if filepath not in root_inventory:
                    print(f"Warning: New file {filepath} found in version {version} not in root inventory.")
                elif digest != root_inventory[filepath]:
                    print(f"Warning: Content digest mismatch for {filepath} in version {version}. Expected {root_inventory[filepath]}, got {digest}.")

        # Update root_inventory with current version's inventory
        root_inventory.update(version_inventory)

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isfile(path):
            return 'file'
        elif os.path.isdir(path):
            namaste_path = os.path.join(path, '0=ocfl_root')
            if os.path.isfile(namaste_path):
                return 'root'
            namaste_path = os.path.join(path, '0=ocfl_object')
            if os.path.isfile(namaste_path):
                return 'object'
            return 'unknown directory type'
        else:
            return 'path does not exist'
    except Exception as e:
        return f'error: {str(e)}'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")

    if not isinstance(bug_ids, list) or not all(isinstance(bid, (int, str)) for bid in bug_ids):
        raise ValueError("bug_ids must be a list of integers or strings")

    if 'ids' in params:
        existing_ids = params['ids']
        if not isinstance(existing_ids, list):
            raise ValueError("Existing ids in params must be a list")
        params['ids'] = list(set(existing_ids + bug_ids))
    else:
        params['ids'] = bug_ids

    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    merged_dict = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = {'key_node': key_node, 'value_node': value_node}
        else:
            if isinstance(value_node, MappingNode) and isinstance(merged_dict[key]['value_node'], MappingNode):
                # Deep merge MappingNodes
                existing_mapping = merged_dict[key]['value_node'].value
                new_mapping = value_node.value
                existing_dict = {k.value: v for k, v in existing_mapping}
                new_dict = {k.value: v for k, v in new_mapping}
                merged_values = {**existing_dict, **new_dict}
                merged_mapping = [(ScalarNode(tag=k.tag, value=k.value), v) for k, v in merged_values.items()]
                merged_dict[key]['value_node'].value = merged_mapping
            else:
                # Last value wins for non-MappingNode values
                merged_dict[key]['value_node'] = value_node

    return [(v['key_node'], v['value_node']) for v in merged_dict.values()]

