def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")
    if number < 0:
        raise ValueError("Number must be non-negative.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))
    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise ValueError("flow_params must be a dictionary")
    if not isinstance(register_number, int) or register_number < 0:
        raise ValueError("register_number must be a non-negative integer")

    for key, value in flow_params.items():
        if isinstance(value, dict):
            _replace_register(value, register_number, register_value)
        elif value == register_value:
            flow_params[key] = register_number

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise ValueError("The value argument must be a string.")
    if not isinstance(arg, str):
        raise ValueError("The arg argument must be a string.")
    return value.replace('.', arg)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet or not string:
        raise ValueError("Both string and alphabet must be non-empty.")

    base = len(alphabet)
    try:
        return sum(alphabet.index(char) * (base ** power) for power, char in enumerate(reversed(string)))
    except ValueError:
        raise ValueError(f"Character in string not found in alphabet: {string}")

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    regex_map = {
        '*': '.*',
        '.': '\\.'
    }
    converted_dict = {}

    for key, value in item.items():
        if isinstance(key, str):
            # Replace wildcards with regex
            regex_key = re.escape(key)
            for wildcard, regex in regex_map.items():
                regex_key = regex_key.replace(re.escape(wildcard), regex)
            converted_dict[regex_key] = value
        else:
            raise ValueError(f"Key {key} is not a string and cannot be converted to a regex.")

    return converted_dict

