def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if roots is None:
        roots = set(graph.subjects()).difference(graph.objects())

    # Iteratively remove non-root nodes
    non_roots = set()
    for child, _, _ in graph.triples((None, prop, None)):
        if child in roots:
            roots.remove(child)
            non_roots.add(child)
        while non_roots:
            current = non_roots.pop()
            for _, _, parent in graph.triples((current, prop, None)):
                if parent in roots:
                    roots.remove(parent)
                    non_roots.add(parent)

    return roots

