def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        # Assuming 'doc' is an XML document and 'signature' is the signature to verify
        # and 'public_key' is the public key used for verification
        from xml.etree import ElementTree
        from xml.dom import minidom
        from OpenSSL import crypto

        # Parse the XML document
        if isinstance(doc, str):
            doc = minidom.parseString(doc)
        else:
            raise ValueError("Document must be a string containing XML.")

        # Convert the XML document to a string for signature verification
        doc_str = doc.toxml()

        # Load the public key
        if isinstance(public_key, str):
            public_key = crypto.load_publickey(crypto.FILETYPE_PEM, public_key)
        elif isinstance(public_key, crypto.PKey):
            pass
        else:
            raise ValueError("Public key must be a PEM string or an OpenSSL PKey object.")

        # Verify the signature
        try:
            crypto.verify(public_key, signature, doc_str, 'sha256')
            return True
        except crypto.Error:
            return False

    except Exception as e:
        raise ValueError(f"An error occurred during signature verification: {str(e)}")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET
    from xml.parsers.expat import ExpatError

    try:
        # Try to parse as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        try:
            # If JSON fails, try to parse as XRD
            root = ET.fromstring(document)
            if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                raise ValueError("Invalid XRD document")

            subject = root.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject')
            aliases = root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias')
            links = root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link')

            parsed_data = {
                'subject': subject.text if subject is not None else None,
                'aliases': [alias.text for alias in aliases],
                'links': [
                    {
                        'rel': link.get('rel'),
                        'href': link.get('href'),
                        'type': link.get('type'),
                        'title': link.get('title'),
                        'template': link.get('template'),
                    }
                    for link in links
                ]
            }
            return parsed_data
        except ExpatError:
            raise ValueError("Unable to parse document as either JSON or XRD")
        except AttributeError:
            raise ValueError("Invalid XRD document structure")

