def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    import xml.etree.ElementTree as ET

    try:
        base_url = "https://diaspora.software/webfinger?q=acct:{}"
        response = requests.get(base_url.format(handle), timeout=10)
        response.raise_for_status()

        root = ET.fromstring(response.content)
        parsed_data = {}

        for element in root:
            if 'xmlns' in element.tag:
                tag_name = element.tag.split('}', 1)[1]
            else:
                tag_name = element.tag

            # Extract text content if available
            if element.text and element.text.strip():
                parsed_data[tag_name] = element.text.strip()

            # Extract attributes
            parsed_data.update(element.attrib)

        return parsed_data

    except requests.exceptions.RequestException as e:
        print(f"Request failed: {e}")
        return {}
    except ET.ParseError as e:
        print(f"XML parsing failed: {e}")
        return {}

