        return defaults
    except Exception as e:
        raise ValueError(f"Error resolving specification defaults: {e}")

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    if not isinstance(cli_args, dict) or not isinstance(answer_file_args, dict):
        raise ValueError("Both cli_args and answer_file_args must be dictionaries.")

    deprecated_args = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2',
        # Add other deprecated arguments here
    }

    all_args = {**cli_args, **answer_file_args}

    for arg, new_arg in deprecated_args.items():
        if arg in all_args:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in future versions. Use '{new_arg}' instead.")
            if new_arg not in all_args:
                print(f"Suggestion: Use '{new_arg}' with the value '{all_args[arg]}'.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        return self.parser_option_specs[command_name]
    except KeyError:
        raise ValueError(f"No options found for command: {command_name}")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise ValueError("Both command_name and argument_name must be strings.")

    if command_name not in self.command_specs:
        raise ValueError(f"Command '{command_name}' not found in specifications.")

    command_spec = self.command_specs[command_name]
    if argument_name not in command_spec.get('options', {}):
        raise ValueError(f"Option '{argument_name}' not found for command '{command_name}'.")

    return command_spec['options'][argument_name]

def get_silent_args(self, args):
    """List of silenced argument names

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary")

    silenced_args = []
    for arg_name, value in args.items():
        if isinstance(value, dict) and value.get('silent', False):
            silenced_args.append(arg_name)
    return silenced_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    missing_args = [arg for arg in self.REQUIRED_ARGS if arg not in args]
    if missing_args:
        raise ValueError(f"Missing required arguments: {', '.join(missing_args)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            condition_met = False
            if isinstance(condition, dict):
                for key, value in condition.items():
                    if args.get(key) == value:
                        condition_met = True
                        break
            elif callable(condition):
                condition_met = condition(args)
            if condition_met:
                matched_args.append(option['name'])
    return matched_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary where keys are argument names and values are tuples of (value, max_length).")

    for arg_name, (value, max_length) in args.items():
        if not isinstance(value, str):
            raise ValueError(f"Value for argument '{arg_name}' must be a string.")
        if not isinstance(max_length, int) or max_length <= 0:
            raise ValueError(f"Max length for argument '{arg_name}' must be a positive integer.")

        if len(value) > max_length:
            raise ValueError(f"Value for argument '{arg_name}' is longer than the maximum allowed length of {max_length} characters.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for arg_name, arg_value in args.items():
        if hasattr(self, arg_name + '_choices'):
            choices = getattr(self, arg_name + '_choices')
            if arg_value not in choices:
                raise ValueError(f"The value for '{arg_name}' must be one of {choices}. Got '{arg_value}' instead.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg, value in args.items():
        min_val = getattr(self, f"{arg}_min", None)
        max_val = getattr(self, f"{arg}_max", None)
        if min_val is not None and value < min_val:
            raise ValueError(f"The value of '{arg}' ({value}) is less than the minimum allowed value ({min_val}).")
        if max_val is not None and value > max_val:
            raise ValueError(f"The value of '{arg}' ({value}) is greater than the maximum allowed value ({max_val}).")

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        complex_type_class = getattr(self, type_name)
    except AttributeError:
        raise ValueError(f"Complex type '{type_name}' not found.")

    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dictionary.")

    try:
        complex_type_instance = complex_type_class(subcommand, option_name, **spec_option)
    except TypeError as e:
        raise ValueError(f"Error creating complex type instance: {e}")

    return complex_type_instance

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if not isinstance(args, dict):
        raise ValueError("The provided arguments must be in the form of a dictionary.")

    for arg_key, arg_value in args.items():
        if arg_key.startswith('control_'):
            control_args[arg_key] = arg_value
        elif arg_key.startswith('custom_'):
            # Custom arguments are directly added to nested_args as they are considered part of the nested usage
            nested_args[arg_key[len('custom_'):]] = arg_value
        else:
            nested_args[arg_key] = arg_value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = []
    for var in extra_vars:
        if isinstance(var, dict):
            vars_dict.update(var)
        else:
            try:
                key, value = var.split('=', 1)
                vars_dict[key] = value
            except ValueError:
                raise ValueError(f"Invalid extra-vars format: {var}")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess

    if not playbook_path:
        raise ValueError("Playbook path must be provided.")

    command = ["ansible-playbook", playbook_path]

    if verbose:
        command.extend(['-'] * verbose)

    if extra_vars:
        extra_vars_str = ','.join(f"{k}={v}" for k, v in extra_vars.items())
        command.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for key, value in ansible_args.items():
            if value is True:
                command.append(f"--{key}")
            elif value is False:
                continue
            else:
                command.extend([f"--{key}", str(value)])

    try:
        result = subprocess.run(command, check=True, text=True, capture_output=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible playbook execution failed: {e.stderr}") from e

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    try:
        if parser_name == 'main':
            if 'age' in values_dict:
                values_dict['age'] = int(values_dict['age'])
            if 'is_active' in values_dict:
                values_dict['is_active'] = values_dict['is_active'].lower() in ['true', '1', 'yes']
        elif parser_name == 'virsh':
            if 'timeout' in values_dict:
                values_dict['timeout'] = float(values_dict['timeout'])
        elif parser_name == 'ospd':
            if 'port' in values_dict:
                values_dict['port'] = int(values_dict['port'])
    except (ValueError, KeyError) as e:
        raise ValueError(f"Error converting argument values for parser {parser_name}: {e}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    plugin_spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    if not os.path.exists(plugin_spec_path):
        raise FileNotFoundError(f"Plugin spec file not found at {plugin_spec_path}")

    with open(plugin_spec_path, 'r') as file:
        plugin_spec = json.load(file)

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(plugin_spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    if 'CONFIG_PATH' not in os.environ:
        try:
            # Assuming a default configuration path, modify as necessary
            default_config_path = '/path/to/default/config'
            os.environ['CONFIG_PATH'] = default_config_path
        except Exception as e:
            raise RuntimeError(f"Failed to set CONFIG_PATH environment variable: {str(e)}")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    stripped_path = path[len(root):]
    # Remove any leading separator if present
    if stripped_path.startswith(os.path.sep):
        stripped_path = stripped_path[len(os.path.sep):]
    return stripped_path
